SELECT count(*) AS shift_records, coalesce(sum(setups),0) AS setup_records, coalesce(list_unique(flatten(list(wet_end_ids))),0) AS paper_changes, coalesce(sum(lineal_ft),0) AS lineal_ft, coalesce(sum(gross_sqft),0) AS gross_sqft, coalesce(sum(trim_sqft),0) AS trim_sqft, coalesce(sum(shear_sqft),0) AS shear_sqft, coalesce(sum(reject_sqft),0) AS reject_sqft, coalesce(sum(elapsed_seconds),0) AS elapsed_seconds, coalesce(sum(setup_stop_seconds),0) AS setup_stop_seconds, count(DISTINCT production_date) FILTER (WHERE setups > 0) AS production_days, coalesce(sum(scheduled_seconds),0) AS scheduled_seconds, coalesce(sum(bale_sqft),0) AS bale_sqft, coalesce(sum(stops),0) AS stop_count, coalesce(sum(stop_seconds),0) AS stop_seconds, coalesce(sum(maintenance_seconds + pm_seconds),0) AS maintenance_pm_seconds, coalesce(sum(operator_seconds),0) AS operator_seconds, coalesce(sum(bond_sqft),0) AS bond_sqft, coalesce(sum(warp_sqft),0) AS warp_sqft, coalesce(sum(misalignment_sqft),0) AS misalignment_sqft, coalesce(sum(moisture_sqft),0) AS moisture_sqft FROM shift_kpis WHERE NOT corrupt AND production_date BETWEEN ? AND ? AND shift = ?;
